// Storage contract for auth. Implementations: ./repositories/mongo/, ./repositories/drizzle/
// All ids are strings (UUIDs generated by the service; token/code ids are SHA-256 hex hashes).
// Expiry is always re-checked by the service, so implementations may purge lazily.

import type { HashAlgorithm } from "../shared/hashing.js";
import type {
  AccessToken,
  AccountUpdate,
  AuthCode,
  AuthRequest,
  Credential,
  Device,
  DeviceSignIn,
  EmailChallenge,
  OAuthClient,
  RefreshToken,
  Role,
  User,
  UserRef,
  UserSummary,
  WebAuthnChallenge,
  WebAuthnCredential
} from "./model.js";

/** Thrown by `create` methods when a unique constraint is violated. */
export class DuplicateKeyError extends Error {
  constructor(
    /** Which unique value collided. */
    readonly field: "username" | "email" | "credential" | "id",
    message = `${field} already exists`
  ) {
    super(message);
  }
}

export interface UserRepository {
  /** @throws DuplicateKeyError (field "username" | "email" | "credential") */
  create(user: User): Promise<void>;
  /** Applies only the given fields; `profiles` replaces the whole list. @throws DuplicateKeyError (field "email") */
  updateAccount(userId: string, update: AccountUpdate): Promise<void>;
  findById(id: string): Promise<User | null>;
  /** All users, oldest first (admin listing). */
  list(): Promise<UserSummary[]>;
  setRoles(userId: string, roles: Role[]): Promise<void>;
  findByUsername(username: string): Promise<User | null>;
  /** id + username only (no profiles / credentials). */
  findRefByUsername(username: string): Promise<UserRef | null>;
  /** id + username for many users in one query; unknown ids are left out. */
  findRefs(ids: string[]): Promise<UserRef[]>;
  /** `email` is already lowercased. */
  findByEmail(email: string): Promise<User | null>;
  /** Marks the email verified, but only while the user still has exactly this address. @returns whether it did */
  markEmailVerified(userId: string, email: string, at: Date): Promise<boolean>;
  /** Finds the owner of a passkey. */
  findByWebAuthnCredId(credId: string): Promise<{ user: User; credential: WebAuthnCredential } | null>;

  /** @throws DuplicateKeyError when a passkey with the same credId is registered (to anyone) */
  addCredential(userId: string, credential: Credential): Promise<void>;
  /** Replace the hash of a secret credential (rehash / algorithm upgrade / secret change). */
  updateSecret(userId: string, credentialId: string, value: string, algorithm: HashAlgorithm): Promise<void>;
  recordWebAuthnUse(userId: string, credentialId: string, counter: number, usedAt: Date): Promise<void>;
  /** Renames one of the user's passkeys. @returns false if the user has no passkey with this id */
  renameWebAuthn(userId: string, credentialId: string, name: string): Promise<boolean>;
  /**
   * Removes a credential unless it is the user's last one.
   * @returns "removed" | "not_found" | "last_credential"
   */
  removeCredential(userId: string, credentialId: string): Promise<"removed" | "not_found" | "last_credential">;
}

export interface ChallengeRepository {
  create(challenge: WebAuthnChallenge): Promise<void>;
  /** Atomically delete and return (single use). */
  consume(id: string, type: WebAuthnChallenge["type"]): Promise<WebAuthnChallenge | null>;
}

export interface EmailChallengeRepository {
  create(challenge: EmailChallenge): Promise<void>;
  findActive(id: string, now: Date): Promise<EmailChallenge | null>;
  /** Atomically count a wrong code; returns the new attempt count, or null if the challenge is gone. */
  recordFailedAttempt(id: string): Promise<number | null>;
  /** Link confirmed: set approvedAt. @returns false if the challenge is gone */
  approve(id: string, at: Date): Promise<boolean>;
  /** Resend: store the new code hash, reset attempts and count the send. */
  replaceCode(id: string, codeHash: string, sentAt: Date, expiresAt: Date): Promise<void>;
  /** Atomically delete; true only for the caller that removed it (single use). */
  consume(id: string): Promise<boolean>;
}

export interface DeviceRepository {
  /**
   * Upsert by (userId, keyHash): a new device gets `id` and createdAt; an existing one gets the latest
   * name/userAgent/ip/method, lastSignInAt = lastSeenAt = at, and signIns + 1. @returns the device's id
   */
  recordSignIn(signIn: DeviceSignIn): Promise<string>;
  /** Most recently seen first. */
  listByUser(userId: string): Promise<Device[]>;
  touch(id: string, at: Date): Promise<void>;
  /** @returns whether a device of this user was deleted */
  delete(userId: string, id: string): Promise<boolean>;
}

export interface ClientRepository {
  /** @throws DuplicateKeyError (field "id") */
  create(client: OAuthClient): Promise<void>;
  findById(id: string): Promise<OAuthClient | null>;
  /** Oldest first. */
  list(): Promise<OAuthClient[]>;
  /** Replaces every field but id/createdAt. @returns false if there is no such client */
  update(client: OAuthClient): Promise<boolean>;
  delete(id: string): Promise<boolean>;
}

/** Server-wide settings: JSON values by key. */
export interface SettingsRepository {
  get<T>(key: string): Promise<T | null>;
  set(key: string, value: unknown): Promise<void>;
  delete(key: string): Promise<void>;
}

export interface AuthRequestRepository {
  create(req: AuthRequest): Promise<void>;
  findActive(id: string, now: Date): Promise<AuthRequest | null>;
  /** Atomically delete and return if not expired. */
  consumeActive(id: string, now: Date): Promise<AuthRequest | null>;
}

export interface AuthCodeRepository {
  create(code: AuthCode): Promise<void>;
  /** Atomically flip used=false -> true and return the code; null if missing or already used. */
  redeem(id: string): Promise<AuthCode | null>;
  find(id: string): Promise<AuthCode | null>;
}

export interface TokenRepository {
  /** Persist an access token and, when the client may refresh, its refresh token (atomically where possible). */
  createPair(access: AccessToken, refresh: RefreshToken | null): Promise<void>;
  findActiveAccess(id: string, now: Date): Promise<AccessToken | null>;
  findAccess(id: string): Promise<AccessToken | null>;
  findRefresh(id: string): Promise<RefreshToken | null>;
  /** Atomically flip revoked=false -> true and return the token; null if missing or already revoked. */
  rotateRefresh(id: string): Promise<RefreshToken | null>;
  /** Revoke every refresh token and delete every access token in the family. */
  revokeFamily(familyId: string): Promise<void>;
  /** Same as revokeFamily, for every session the user started on the device. */
  revokeDevice(userId: string, deviceId: string): Promise<void>;
  /** Every token issued to the client (client deleted / secret compromised). */
  revokeClient(clientId: string): Promise<void>;
  /** Devices of the user that still hold a usable (unrevoked, unexpired) refresh token. */
  activeDeviceIds(userId: string, now: Date): Promise<string[]>;
}

export interface AuthRepository {
  readonly users: UserRepository;
  readonly challenges: ChallengeRepository;
  readonly emailChallenges: EmailChallengeRepository;
  readonly devices: DeviceRepository;
  readonly clients: ClientRepository;
  readonly settings: SettingsRepository;
  readonly authRequests: AuthRequestRepository;
  readonly authCodes: AuthCodeRepository;
  readonly tokens: TokenRepository;

  /**
   * Create indexes / run migrations, and start any background upkeep the backend needs
   * (e.g. sweeping expired rows where the database has no TTL).
   */
  init(): Promise<void>;
  /** Stop background upkeep and disconnect. */
  close(): Promise<void>;
}
